local util = require 'XLua.util'
local CoWait = CS.Engine.Lib.CoWait

------------ import ------------
local UIEventProxy = CS.Engine.UI.UIEventProxy
local UIModule = CS.Engine.UI.UIModule
local KTool = CS.Engine.Lib.KTool
local gameUtils = CS.GameUtils
local ReverseScale = CS.Game.Native.Common.ReverseScale
local settingMgr = SettingMgr:GetInstance()
------------ import ------------

------------ define ------------
local PrefabName = "EquipNode"
local GoodsNodePath = "Game.Behaviours.GoodNodeMB"
local cardConfMgr = CardConfMgr:GetInstance()
------------ define ------------

---@class MatResolveDialog
---@field Txt_NotSelected                UnityEngine.RectTransform
---@field NoText                            UnityEngine.UI.Text
---@field ResolveButton                    UnityEngine.RectTransform
---@field GainNode                        UnityEngine.RectTransform
---@field GainLayout                        UnityEngine.RectTransform
---@field GridView                        SuperScrollView.LoopGridView
---@field CloseButton                    UnityEngine.RectTransform
local MatResolveDialog = Class("MatResolveDialog")

function MatResolveDialog:__init()
    self.data = nil
    self.select = {} ---选中的部位
    self.equipDiySuitData = {} --- <equipId, <number, suitId>>
end

function MatResolveDialog:__delete()
    self.data = nil
    self.select = nil
    self.equipDiySuitData = nil
end

function MatResolveDialog:Awake()
    self:InitDiySuitData()

    self.GridView:InitGridView(0, Bind(self, self.OnGetItemByIndex))
    UIEventProxy.Create(self.CloseButton.gameObject).onPointerClick = function(pointerEventData)
        UIModule.BackDialog()
    end

    UIEventProxy.Create(self.ResolveButton.gameObject).onPointerClick = function(pointerEventData)
        ---分解按钮事件
        if table.count(self.select) > 0 then
            --- 初始化再组合中的装备数据
            local waitRemoveList = {}
            for i, equipId in ipairs(self.select) do
                local playerEquipId = checkInt(equipId)
                local suitList = self.equipDiySuitData[checkInt(playerEquipId)]
                if suitList then
                    for _, suitId in ipairs(suitList) do
                        waitRemoveList[suitId] = waitRemoveList[suitId] or {}
                        waitRemoveList[suitId][playerEquipId] = playerEquipId
                    end
                end
            end

            local isSelectInDiySuitEquip = next(waitRemoveList) ~= nil
            local cb = function()
                local str = table.concat(self.select, ',')
                GameUtils.Request(Interfaces.BackpackDecompose, { equipments = str }, function(request, responseTable)
                    if responseTable and checkNumber(responseTable.errCode) == 0 then
                        local rewards = responseTable.data.rewards
                        if isTable(rewards) then
                            ---删除装备
                            ---@type EquipmentComponent
                            local equipComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
                            equipComp:RemoveEquipsByIdList(self.select)
                            GoodsUtils.DrawRewards(rewards, true)
                            self:FreshGridView()
                            ---更新界面ui
                            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })

                            if isSelectInDiySuitEquip then
                                equipComp:RemoveInlaidDiySuitEquip(waitRemoveList)
                            end
                        end
                    end
                end, function(exception)
                    GameUtils.Toast(exception.Message)
                end)
            end

            if isSelectInDiySuitEquip then
                GameUtils.SecondConfirm(localize("该装备在组合中是否确认分解"), function()
                    cb()
                    return true
                end)
            else
                cb()
            end

        else
            GameUtils.Toast(localize('请选择要分解的情绪涂鸦'))
        end
    end
end

function MatResolveDialog:InitDiySuitData()
    ---@type EquipmentComponent
    local equipComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
    local diySuits = equipComp:GetDiySuits()
    local equipDiySuitData = {}
    for i, v in ipairs(diySuits) do
        local suitId = checkNumber(v.suitId)
        if suitId > 0 then
            local equipIdList = string.split(v.equipments, ',')
            for _, equipId in ipairs(equipIdList) do
                local playerEquipId = checkInt(equipId)
                if playerEquipId > 0 then
                    equipDiySuitData[playerEquipId] = equipDiySuitData[playerEquipId] or {}
                    table.insert(equipDiySuitData[playerEquipId], suitId)
                end
            end
        end

    end
    print(table.dump(equipDiySuitData))
    self.equipDiySuitData = equipDiySuitData
end

---FreshGridView
---刷新gridview列表数据
function MatResolveDialog:FreshGridView()
    local parameters = self.controller.Argument.parameters
    local excludeId = 0
    if not isNull(parameters) then
        local attachParams = parameters.attachParams or {}
        excludeId = checkNumber(attachParams.excludeId)
    end
    --刷新列表
    self.data = {}
    self.select = {}
    ---@type EquipmentComponent
    local equipComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
    local equips = equipComp:GetAllEquips()
    for i, v in pairs(equips) do
        if checkInt(v.playerCardId) <= 0 and checkInt(v.locked) == 0 and checkNumber(v.id) ~= excludeId then
            ---已经被其他角色装备或者被锁定的装备不参与分解
            table.insert(self.data, v)
        end
    end
    ---@type SuperScrollView.LoopStaggeredGridView
    local gridView = self.GridView
    local len = table.count(self.data)
    KTool.SetActive(self.GridView.gameObject, len > 0)
    KTool.SetActive(self.NoText.gameObject, len == 0)
    --if len > 0 then
    --    ---大于1的数量0
    --    ---@type EquipDojo
    --    local dojo = self.data[1]
    --    table.insert(self.select, checkInt(dojo.id))
    --end
    --- 刷新 是否有选中装备文字描述状态
    KTool.SetActive(self.Txt_NotSelected.gameObject, true)
    GameUtils.ReloadData(gridView, len)
    self:FreshBottomPreviewNode()
end

---OnGetItemByIndex
---@param listView SuperScrollView.LoopGridView
---@param index number
---@return SuperScrollView.LoopGridView
function MatResolveDialog:OnGetItemByIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end
    if self.data == nil then
        return nil
    end
    local position = index + 1
    if #self.data < position then
        return nil
    end
    local cell = listView:NewListViewItem(PrefabName)
    ---@type EquipDojo
    local dojo = self.data[position]
    if not isNull(dojo) then
        local goodNodeTrans = cell.transform:Find("GoodNode")
        if not isNull(goodNodeTrans) then
            local reScale = goodNodeTrans.gameObject:GetComponent(typeof(ReverseScale))
            reScale:ResetScale()
            local goodItemNodeMB = GetLuaBehaviour(goodNodeTrans.gameObject, GoodsNodePath)
            if not isNull(goodItemNodeMB) then
                if isNull(goodItemNodeMB.Env) then
                    goodItemNodeMB:Init()
                end
                ---@type GoodNodeMB
                local goodItemNodeEnv = goodItemNodeMB.Env
                goodItemNodeEnv:Reload({
                    id = dojo.id, dojo = dojo, goodsId = dojo.equipmentId
                })
                ---选中状态
                goodItemNodeEnv:SetCheckState(table.indexof(self.select, checkInt(dojo.id)) ~= false)
                goodItemNodeEnv:SetClickButtonAction(function(goodsId)
                    ---选中按钮
                    if table.indexof(self.select, checkInt(dojo.id)) then
                        table.removebyvalue(self.select, checkInt(dojo.id))
                    else
                        table.insert(self.select, checkInt(dojo.id))
                    end
                    goodItemNodeEnv:SetCheckState(table.indexof(self.select, checkInt(dojo.id)) ~= false)
                    self:FreshBottomPreviewNode()
                end)
            end
        end
    end
    return cell
end

---FreshBottomDetailNode
---刷新最下方的分解预览信息的
function MatResolveDialog:FreshBottomPreviewNode()
    KTool.DestroyGameObjectChildren(self.GainLayout.gameObject, false)
    if table.count(self.select) > 0 then
        --- 刷新 是否有选中装备文字描述状态
        KTool.SetActive(self.Txt_NotSelected.gameObject, false)
        ---@type TableML.TableFile
        local iDGroupTableFile = settingMgr:Get(string.format('%sIDGroup',AutoIds.IdSetting36))
        local tableFile = settingMgr:Get(AutoIds.IdSetting36)
        ---@type EquipmentComponent
        local equipComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
        local part2No = {}
        for _, id in pairs(self.select) do
            local equipDojo = equipComp:GetEquipById(id)
            ---@type EquipVo
            local vo = CardConfMgr:GetInstance():GetEquipVoById(equipDojo.equipmentId)
            ---@type TableML.TableFileRow
            local groupRow = iDGroupTableFile:GetByPrimaryKey(string.format('%s_%s', tostring(vo.resolveType), tostring(vo.part)))
            ---@type TableML.TableFileRow
            local row = tableFile:GetByPrimaryKey(groupRow:Get("id"))
            local goodsId = row:Get("reward")
            local maxNum = row:Get("rewardMaxNum")
            local key = tostring(vo.part)
            if isNull(part2No[key]) then
                part2No[key] = { goodsId = goodsId, num = maxNum }
            else
                part2No[key].num = checkInt(part2No[key].num) + maxNum
            end
        end

        local keys = sortByKey(part2No)
        for _, part in pairs(keys) do
            local t = part2No[part]
            local go = KTool.Instantiate(self.GainLayout.gameObject, self.GainNode.gameObject)
            KTool.SetActive(go, true)
            ---@type UnityEngine.Transform
            local goodNodeTrans = go.transform:Find("GoodNode")
            if not isNull(goodNodeTrans) then
                local goodItemNodeMB = GetLuaBehaviour(goodNodeTrans.gameObject, GoodsNodePath)
                if not isNull(goodItemNodeMB) then
                    if isNull(goodItemNodeMB.Env) then
                        goodItemNodeMB:Init()
                    end
                    ---@type GoodNodeMB
                    local goodItemNodeEnv = goodItemNodeMB.Env
                    goodItemNodeEnv:Reload({
                        goodsId = t.goodsId, isShowNo = true, text = string.format('x%d', checkNumber(t.num))
                    })
                    goodItemNodeEnv:SetPreviewText(string.format('x%d', checkNumber(t.num)))
                    goodItemNodeEnv:SetClickButtonAction(function(goodsId)
                        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                        if isTable(vo) then
                            GameUtils.ShowCommonTipsBoard(go, vo.name, vo.desc, vo.quality, vo.id)
                        end
                    end)
                end
            end
        end
    else
        --- 刷新 是否有选中装备文字描述状态
        KTool.SetActive(self.Txt_NotSelected.gameObject, true)
    end
end

function MatResolveDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:FreshGridView()
    end))
    return coWait
end

function MatResolveDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return MatResolveDialog